'use client'

import { useCallback, useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import ModeratorShell, { useModeratorAuth } from '../ModeratorShell'

type Farmer = {
  id: string
  slug: string
  name: string
  village: string | null
  district: string | null
  method: string | null
  phone: string | null
  active: boolean
  listing_count: number
}

const METHOD_LABEL: Record<string, string> = {
  natural: 'Natural',
  low_chemical: 'Low chem',
  chemical: 'Chemical',
}

export default function ModeratorFarmersPage() {
  const router = useRouter()
  const { zone, checked } = useModeratorAuth()
  const [farmers, setFarmers] = useState<Farmer[]>([])
  const [error, setError] = useState('')
  const [busyId, setBusyId] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)

  const load = useCallback(async () => {
    const r = await fetch('/api/moderator/farmers', { credentials: 'same-origin' }).catch(() => null)
    setLoading(false)
    if (!r) { setError('Network error.'); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not load farmers.'); return }
    setFarmers((json.farmers ?? []) as Farmer[])
  }, [])

  useEffect(() => { if (checked) void load() }, [checked, load])

  const toggleActive = async (f: Farmer) => {
    if (busyId) return
    setBusyId(f.id)
    const r = await fetch(`/api/moderator/farmers/${f.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ active: !f.active }),
    }).catch(() => null)
    setBusyId(null)
    if (!r || !r.ok) { setError('Update failed.'); return }
    setFarmers((list) => list.map((x) => (x.id === f.id ? { ...x, active: !x.active } : x)))
  }

  if (!checked || !zone) {
    return (
      <main className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin" />
      </main>
    )
  }

  const activeCount = farmers.filter((f) => f.active).length

  return (
    <ModeratorShell title="Farmer onboarding" subtitle="Register a new farmer or manage existing ones" zone={zone}>
      <div className="flex items-center justify-between mb-4">
        <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wide">
          {activeCount} active farmer{activeCount !== 1 ? 's' : ''} in zone
        </p>
        <button
          onClick={() => router.push('/moderator/register-farmer')}
          className="bg-green-800 text-white text-sm font-bold px-4 py-2 rounded-xl active:bg-green-900"
        >
          + Add new farmer
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-xl px-4 py-2 text-sm font-semibold mb-4">{error}</div>
      )}

      {loading ? (
        <p className="text-sm text-gray-400 py-10 text-center">Loading…</p>
      ) : farmers.length === 0 ? (
        <div className="text-center py-14 bg-white rounded-2xl border border-gray-100">
          <div className="text-5xl mb-3">🌾</div>
          <p className="font-semibold text-gray-500 text-sm">No farmers yet in this zone</p>
        </div>
      ) : (
        <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
          {/* header row — hidden on mobile */}
          <div className="hidden md:grid grid-cols-12 gap-2 px-4 py-2.5 text-[10px] font-bold text-gray-400 uppercase border-b border-gray-100">
            <div className="col-span-4">Farmer</div>
            <div className="col-span-3">Village</div>
            <div className="col-span-2">Method</div>
            <div className="col-span-1 text-center">Listings</div>
            <div className="col-span-2 text-right">Status</div>
          </div>
          {farmers.map((f) => (
            <div key={f.id} className="grid grid-cols-12 gap-2 items-center px-4 py-3 border-b border-gray-50 last:border-0">
              <div className="col-span-12 md:col-span-4 min-w-0">
                <p className="font-bold text-gray-900 text-sm truncate">{f.name}</p>
                <a href={`/farmer/${f.slug}`} target="_blank" className="text-[11px] text-green-700 underline">/farmer/{f.slug}</a>
              </div>
              <div className="col-span-6 md:col-span-3 text-sm text-gray-600 truncate">{f.village || '—'}</div>
              <div className="col-span-6 md:col-span-2">
                <span className="text-[11px] font-semibold bg-green-100 text-green-800 px-2 py-0.5 rounded-full">
                  {METHOD_LABEL[f.method ?? ''] ?? f.method ?? '—'}
                </span>
              </div>
              <div className="col-span-4 md:col-span-1 text-sm text-gray-700 md:text-center">{f.listing_count}</div>
              <div className="col-span-8 md:col-span-2 flex items-center justify-end gap-2">
                <span className={`text-[11px] font-semibold px-2 py-0.5 rounded-full ${f.active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-500'}`}>
                  {f.active ? 'Active' : 'Inactive'}
                </span>
                <button
                  onClick={() => toggleActive(f)}
                  disabled={busyId === f.id}
                  className="text-[11px] text-gray-500 underline disabled:opacity-50"
                >
                  {f.active ? 'Deactivate' : 'Activate'}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </ModeratorShell>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { isModeratorRequest, getModeratorZone } from '@/lib/moderator-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const METHODS = ['natural', 'low_chemical', 'chemical'] as const

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

// PATCH — edit farmer details or toggle active status. Scoped to the zone so a
// moderator can never touch a farmer outside their own region.
export async function PATCH(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const { id } = await params
  const zone = getModeratorZone(req)
  const supabase = svc()

  // Confirm the farmer belongs to this moderator's zone before any write.
  const { data: farmer } = await supabase
    .from('farmers')
    .select('id, region_slug')
    .eq('id', id)
    .maybeSingle()
  if (!farmer || farmer.region_slug !== zone) {
    return NextResponse.json({ error: 'Farmer not found in your zone.' }, { status: 404 })
  }

  const body = await req.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid body.' }, { status: 400 })
  const b = body as Record<string, unknown>

  const update: Record<string, unknown> = {}
  if ('name' in b) update.name = String(b.name ?? '').trim()
  if ('phone' in b) update.phone = String(b.phone ?? '').trim() || null
  if ('village' in b) update.village = String(b.village ?? '').trim() || null
  if ('district' in b) update.district = String(b.district ?? '').trim() || null
  if ('story_quote' in b) update.story_quote = String(b.story_quote ?? '').trim() || null
  if ('farm_size_acres' in b) update.farm_size_acres = Number(b.farm_size_acres) || null
  if ('farming_since_year' in b) update.farming_since_year = Number(b.farming_since_year) || null
  if ('active' in b) update.active = Boolean(b.active)
  if ('method' in b) {
    const m = String(b.method ?? '')
    if ((METHODS as readonly string[]).includes(m)) update.method = m
  }

  if (Object.keys(update).length === 0) {
    return NextResponse.json({ error: 'Nothing to update.' }, { status: 400 })
  }

  const { data: updated, error } = await supabase
    .from('farmers')
    .update(update)
    .eq('id', id)
    .select('id, slug, name, phone, village, district, method, active')
    .single()

  if (error) {
    console.error('[YFF moderator/farmers PATCH] failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  return NextResponse.json({ farmer: updated })
}

import { createClient } from '@supabase/supabase-js'
import { randomInt } from 'crypto'
import { NextRequest, NextResponse } from 'next/server'
import { isModeratorRequest, getModeratorZone, getModeratorId } from '@/lib/moderator-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const METHODS = ['natural', 'organic', 'low_chemical', 'chemical'] as const

// Unambiguous alphabet for activation codes — no 0/O/1/I/L so a farmer reading
// the code off WhatsApp can't mistype it.
const CODE_ALPHABET = 'REDACTED'

function slugify(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
}

// A shareable activation code, e.g. "YFF-7K9Q". Caller checks DB uniqueness.
function makeActivationCode(): string {
  let s = ''
  for (let i = 0; i < 4; i++) s += CODE_ALPHABET[randomInt(CODE_ALPHABET.length)]
  return `YFF-${s}`
}

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

// GET — farmers in the moderator's zone, with a live listing count.
// `?mine=1` narrows to farmers this moderator personally onboarded (for the
// my-farmers page) and includes the activation code so it can be re-shared.
export async function GET(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone(req)
  const mineOnly = req.nextUrl.searchParams.get('mine') === '1'
  const moderatorId = getModeratorId(req)
  const supabase = svc()

  let query = supabase
    .from('farmers')
    .select('id, slug, name, village, district, method, phone, active, created_at, activation_code, registered_by_moderator')
    .eq('region_slug', zone)
    .order('created_at', { ascending: false })

  if (mineOnly) {
    // A legacy session (no id) has no "mine" — return an empty list rather than
    // leaking the whole zone, prompting a re-login to populate the id.
    if (!moderatorId) return NextResponse.json({ farmers: [], needsRelogin: true })
    query = query.eq('registered_by_moderator', moderatorId)
  }

  const { data: farmers, error } = await query

  if (error) {
    console.error('[YFF moderator/farmers] query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  // Listing count per farmer (one grouped query, merged in JS).
  const ids = (farmers ?? []).map((f) => f.id)
  const counts: Record<string, number> = {}
  if (ids.length > 0) {
    const { data: listings } = await supabase
      .from('produce_listings')
      .select('farmer_id')
      .in('farmer_id', ids)
    for (const l of listings ?? []) {
      if (l.farmer_id) counts[l.farmer_id] = (counts[l.farmer_id] ?? 0) + 1
    }
  }

  const withCounts = (farmers ?? []).map((f) => ({ ...f, listing_count: counts[f.id] ?? 0 }))
  return NextResponse.json({ farmers: withCounts })
}

// POST — register a new farmer in the zone. Auto-generates a unique slug.
export async function POST(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone(req)
  const supabase = svc()

  const body = await req.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid body.' }, { status: 400 })

  const name = String((body as { name?: unknown }).name ?? '').trim()
  const phone = String((body as { phone?: unknown }).phone ?? '').trim()
  const village = String((body as { village?: unknown }).village ?? '').trim()
  const district = String((body as { district?: unknown }).district ?? '').trim()
  const methodRaw = String((body as { method?: unknown }).method ?? 'natural').trim()
  const story_quote = String((body as { story_quote?: unknown }).story_quote ?? '').trim()
  const farm_size_acres = Number((body as { farm_size_acres?: unknown }).farm_size_acres ?? 0) || null
  const farming_since_year = Number((body as { farming_since_year?: unknown }).farming_since_year ?? 0) || null

  // Marketing / payout details — the same things a farmer fills on their own
  // profile, so a moderator onboarding on their behalf can capture them up front.
  const farm_address = String((body as { farm_address?: unknown }).farm_address ?? '').trim()
  const upi_id = String((body as { upi_id?: unknown }).upi_id ?? '').trim()
  const cod_enabled = (body as { cod_enabled?: unknown }).cod_enabled === true
  // Bank payout + soil details collected during moderator-led onboarding.
  const bank_account_number = String((body as { bank_account_number?: unknown }).bank_account_number ?? '').trim()
  const bank_ifsc = String((body as { bank_ifsc?: unknown }).bank_ifsc ?? '').trim().toUpperCase()
  const socRaw = (body as { soil_organic_carbon?: unknown }).soil_organic_carbon
  const soil_organic_carbon = Number(socRaw) > 0 ? Number(socRaw) : null

  // Photos & farm GPS — the same media a farmer can attach to their own profile.
  const cover_photo_url = String((body as { cover_photo_url?: unknown }).cover_photo_url ?? '').trim()
  const photo_url = String((body as { photo_url?: unknown }).photo_url ?? '').trim()
  const pesticide_cert_url = String((body as { pesticide_cert_url?: unknown }).pesticide_cert_url ?? '').trim()
  const upi_qr_code_url = String((body as { upi_qr_code_url?: unknown }).upi_qr_code_url ?? '').trim()
  const location_name = String((body as { location_name?: unknown }).location_name ?? '').trim()
  const latRaw = (body as { lat?: unknown }).lat
  const lngRaw = (body as { lng?: unknown }).lng
  const lat = typeof latRaw === 'number' && Number.isFinite(latRaw) ? latRaw : null
  const lng = typeof lngRaw === 'number' && Number.isFinite(lngRaw) ? lngRaw : null

  const rawPickups = (body as { pickup_locations?: unknown }).pickup_locations
  const pickup_locations = Array.isArray(rawPickups)
    ? Array.from(new Set(rawPickups.map((p) => String(p).trim()).filter(Boolean)))
    : []

  // pickup_slots: { days: string[], time_from, time_to } — stored only when at
  // least one day is chosen, matching the farmer-side profile editor.
  const slots = (body as { pickup_slots?: unknown }).pickup_slots as
    | { days?: unknown; time_from?: unknown; time_to?: unknown }
    | null
    | undefined
  const slotDays = Array.isArray(slots?.days) ? slots!.days.map((d) => String(d)).filter(Boolean) : []
  const pickup_slots = slotDays.length > 0
    ? { days: slotDays, time_from: String(slots?.time_from ?? '08:00'), time_to: String(slots?.time_to ?? '12:00') }
    : null

  if (!name) return NextResponse.json({ error: 'Name is required.' }, { status: 400 })
  if (upi_id && !/^[a-zA-Z0-9._-]{2,256}@[a-zA-Z]{2,64}$/.test(upi_id)) {
    return NextResponse.json({ error: 'Invalid UPI ID. Example: name@ybl' }, { status: 400 })
  }
  if (bank_ifsc && !/^[A-Z]{4}0[A-Z0-9]{6}$/.test(bank_ifsc)) {
    return NextResponse.json({ error: 'Invalid IFSC. Example: SBIN0001234' }, { status: 400 })
  }
  const method = (METHODS as readonly string[]).includes(methodRaw) ? methodRaw : 'natural'

  // Unique slug — append -2, -3, ... if taken.
  const base = slugify(name) || 'farmer'
  let slug = base
  for (let i = 2; i < 50; i++) {
    const { data: existing } = await supabase.from('farmers').select('id').eq('slug', slug).maybeSingle()
    if (!existing) break
    slug = `${base}-${i}`
  }

  // Unique activation code to share with the farmer for login activation.
  let activation_code = makeActivationCode()
  for (let i = 0; i < 20; i++) {
    const { data: clash } = await supabase.from('farmers').select('id').eq('activation_code', activation_code).maybeSingle()
    if (!clash) break
    activation_code = makeActivationCode()
  }

  // The moderator who is onboarding this farmer (from their signed session).
  const registered_by_moderator = getModeratorId(req)

  const { data: inserted, error } = await supabase
    .from('farmers')
    .insert({
      slug,
      name,
      phone: phone || null,
      village: village || null,
      district: district || null,
      method,
      story_quote: story_quote || null,
      farm_size_acres,
      farming_since_year,
      farm_address: farm_address || null,
      pickup_locations,
      pickup_slots,
      upi_id: upi_id || null,
      upi_qr_code_url: upi_qr_code_url || null,
      cod_enabled,
      bank_account_number: bank_account_number || null,
      bank_ifsc: bank_ifsc || null,
      soil_organic_carbon,
      cover_photo_url: cover_photo_url || null,
      photo_url: photo_url || null,
      pesticide_cert_url: pesticide_cert_url || null,
      lat,
      lng,
      location_name: lat != null && lng != null ? (location_name || name) : null,
      region_slug: zone,
      active: true,
      activation_code,
      registered_by_moderator,
    })
    .select('id, slug, name, phone, activation_code')
    .single()

  if (error) {
    console.error('[YFF moderator/farmers] insert failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  return NextResponse.json({ farmer: inserted })
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'
import LocationSearch from '@/components/LocationSearch'
import ModeratorShell, { useModeratorAuth } from '../ModeratorShell'

type Created = { id: string; slug: string; name: string; phone: string | null; activation_code: string | null }

// Shrink large camera photos before upload so they stay quick on a 4G connection.
async function compressImage(file: File, maxPx = 800, quality = 0.7): Promise<File> {
  return new Promise((resolve) => {
    const img = new Image()
    const blobUrl = URL.createObjectURL(file)
    img.onload = () => {
      URL.revokeObjectURL(blobUrl)
      const scale = Math.min(1, maxPx / Math.max(img.naturalWidth, img.naturalHeight))
      const canvas = document.createElement('canvas')
      canvas.width = Math.round(img.naturalWidth * scale)
      canvas.height = Math.round(img.naturalHeight * scale)
      const ctx = canvas.getContext('2d')
      if (!ctx) { resolve(file); return }
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height)
      canvas.toBlob(
        (blob) => {
          if (!blob) { resolve(file); return }
          const name = file.name.replace(/\.[^.]+$/, '.jpg')
          resolve(new File([blob], name, { type: 'image/jpeg' }))
        },
        'image/jpeg',
        quality,
      )
    }
    img.onerror = () => { URL.revokeObjectURL(blobUrl); resolve(file) }
    img.src = blobUrl
  })
}

type PhotoState = { file: File | null; preview: string }
const EMPTY_PHOTO: PhotoState = { file: null, preview: '' }

export default function RegisterFarmerPage() {
  const router = useRouter()
  const { zone, checked } = useModeratorAuth()

  const EMPTY_FORM = {
    name: '', phone: '', village: '', district: '',
    method: 'natural', farm_size_acres: '', farming_since_year: '', story_quote: '',
    farm_address: '', upi_id: '', soil_organic_carbon: '',
    bank_account_number: '', bank_ifsc: '',
  }
  const [form, setForm] = useState(EMPTY_FORM)
  const [error, setError] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [created, setCreated] = useState<Created | null>(null)

  // Pickup & payout details (same shape as the farmer's own profile editor).
  const [pickupLocations, setPickupLocations] = useState<string[]>([])
  const [newPickup, setNewPickup] = useState('')
  const [codEnabled, setCodEnabled] = useState(false)

  // Farm GPS location (same as the farmer's own profile editor).
  const [lat, setLat] = useState<number | null>(null)
  const [lng, setLng] = useState<number | null>(null)
  const [locationName, setLocationName] = useState('')
  const [locating, setLocating] = useState(false)
  const [locError, setLocError] = useState('')

  // Photos: cover, avatar, pesticide cert, UPI QR.
  const [cover, setCover] = useState<PhotoState>(EMPTY_PHOTO)
  const [avatar, setAvatar] = useState<PhotoState>(EMPTY_PHOTO)
  const [cert, setCert] = useState<PhotoState>(EMPTY_PHOTO)
  const [qr, setQr] = useState<PhotoState>(EMPTY_PHOTO)

  const resetAll = () => {
    setForm(EMPTY_FORM)
    setPickupLocations([]); setNewPickup('')
    setCodEnabled(false)
    setLat(null); setLng(null); setLocationName(''); setLocError('')
    for (const p of [cover, avatar, cert, qr]) if (p.preview) URL.revokeObjectURL(p.preview)
    setCover(EMPTY_PHOTO); setAvatar(EMPTY_PHOTO); setCert(EMPTY_PHOTO); setQr(EMPTY_PHOTO)
  }

  const pickPhoto = (set: (p: PhotoState) => void, current: PhotoState) => async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    if (!file.type.startsWith('image/')) { setError('Please pick an image file.'); return }
    if (file.size > 8 * 1024 * 1024) { setError('Image is too large (max 8 MB).'); return }
    setError('')
    if (current.preview) URL.revokeObjectURL(current.preview)
    const compressed = await compressImage(file)
    set({ file: compressed, preview: URL.createObjectURL(compressed) })
  }
  const clearPhoto = (set: (p: PhotoState) => void, current: PhotoState) => () => {
    if (current.preview) URL.revokeObjectURL(current.preview)
    set(EMPTY_PHOTO)
  }

  const handleGPS = () => {
    if (!navigator.geolocation) { setLocError('Geolocation not supported on this device.'); return }
    setLocating(true); setLocError('')
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setLat(pos.coords.latitude); setLng(pos.coords.longitude)
        setLocationName(form.village || 'Farm'); setLocating(false)
      },
      (err) => {
        setLocError(err.code === 1
          ? 'Location permission denied. Allow location in browser settings.'
          : 'Could not get location. Please try again.')
        setLocating(false)
      },
      { timeout: 15000, enableHighAccuracy: true },
    )
  }

  // Upload one photo to the shared farm-images bucket. The farmer row doesn't
  // exist yet, so namespace under a temp folder generated for this onboarding.
  const uploadPhoto = async (file: File, folder: string, suffix: string): Promise<string | null> => {
    const ext = file.name.split('.').pop()?.toLowerCase() || 'jpg'
    const path = `${folder}/${suffix}-${Date.now()}.${ext}`
    const { error: upErr } = await supabase.storage
      .from('farm-images')
      .upload(path, file, { contentType: file.type, upsert: false })
    if (upErr) { setError(`Upload failed: ${upErr.message}`); return null }
    return supabase.storage.from('farm-images').getPublicUrl(path).data.publicUrl
  }

  const addPickup = () => {
    const v = newPickup.trim()
    if (!v || pickupLocations.includes(v)) { setNewPickup(''); return }
    setPickupLocations((prev) => [...prev, v]); setNewPickup('')
  }
  const removePickup = (loc: string) => setPickupLocations((prev) => prev.filter((l) => l !== loc))

  const set = (k: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) =>
    setForm((f) => ({ ...f, [k]: e.target.value }))

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (submitting) return
    setError('')
    setSubmitting(true)

    // Upload any chosen photos first; abort the whole save if an upload fails.
    const folder = `onboarding-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
    const [coverUrl, avatarUrl, certUrl, qrUrl] = await Promise.all([
      cover.file ? uploadPhoto(cover.file, folder, 'cover') : Promise.resolve(null),
      avatar.file ? uploadPhoto(avatar.file, folder, 'avatar') : Promise.resolve(null),
      cert.file ? uploadPhoto(cert.file, folder, 'pesticide-cert') : Promise.resolve(null),
      qr.file ? uploadPhoto(qr.file, folder, 'upi-qr') : Promise.resolve(null),
    ])
    if ((cover.file && !coverUrl) || (avatar.file && !avatarUrl) || (cert.file && !certUrl) || (qr.file && !qrUrl)) {
      setSubmitting(false)
      return // error already set by uploadPhoto
    }

    const r = await fetch('/api/moderator/farmers', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({
        ...form,
        pickup_locations: pickupLocations,
        cod_enabled: codEnabled,
        cover_photo_url: coverUrl,
        photo_url: avatarUrl,
        pesticide_cert_url: certUrl,
        upi_qr_code_url: qrUrl,
        lat, lng,
        location_name: lat != null && lng != null ? (locationName || form.village) : null,
      }),
    }).catch(() => null)
    setSubmitting(false)
    if (!r) { setError('Network error.'); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok || !json?.farmer) { setError(json?.error ?? 'Could not save farmer.'); return }
    setCreated(json.farmer as Created)
  }

  if (!checked || !zone) {
    return (
      <main className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin" />
      </main>
    )
  }

  // Success screen: show the activation code to share + profile link.
  if (created) {
    return (
      <ModeratorShell title="Farmer registered" zone={zone}>
        <FarmerCreatedCard
          created={created}
          onAddAnother={() => { setCreated(null); resetAll() }}
          onViewMine={() => router.push('/moderator/my-farmers')}
        />
      </ModeratorShell>
    )
  }

  return (
    <ModeratorShell title="Register new farmer" subtitle="Onboard a farmer on their behalf" zone={zone}>
      <form onSubmit={submit} className="bg-white rounded-2xl border border-gray-100 p-5 max-w-2xl space-y-4">
        <div className="grid md:grid-cols-2 gap-4">
          <Field label="Full name *">
            <input value={form.name} onChange={set('name')} required className={inputCls} autoFocus />
          </Field>
          <Field label="Phone (WhatsApp)">
            <input value={form.phone} onChange={set('phone')} placeholder="+91 94400 12345" className={inputCls} />
          </Field>
          <Field label="Village">
            <input value={form.village} onChange={set('village')} className={inputCls} />
          </Field>
          <Field label="District">
            <input value={form.district} onChange={set('district')} className={inputCls} />
          </Field>
          <Field label="Farming method">
            <select value={form.method} onChange={set('method')} className={inputCls}>
              <option value="natural">Natural (no chemicals)</option>
              <option value="organic">Organic (certified)</option>
              <option value="low_chemical">Low chemical</option>
              <option value="chemical">Chemical</option>
            </select>
          </Field>
          <Field label="Farm size (acres)">
            <input value={form.farm_size_acres} onChange={set('farm_size_acres')} type="number" step="0.1" className={inputCls} />
          </Field>
          <Field label="Farming since (year)">
            <input value={form.farming_since_year} onChange={set('farming_since_year')} type="number" placeholder="2015" className={inputCls} />
          </Field>
          <Field label="Soil organic carbon (%)">
            <input value={form.soil_organic_carbon} onChange={set('soil_organic_carbon')} type="number" step="0.01" placeholder="e.g. 0.85" className={inputCls} />
          </Field>
        </div>
        <Field label="Story / quote">
          <textarea value={form.story_quote} onChange={set('story_quote')} rows={3} className={inputCls} />
        </Field>

        {/* ── Farm location & photos — mirrors the farmer's own profile ── */}
        <div className="border-t border-gray-100 pt-4">
          <p className="text-sm font-extrabold text-green-800 mb-3">Farm location &amp; photos</p>

          <div>
            <span className="text-[11px] font-bold text-gray-500 uppercase tracking-wide block mb-1">Farm location (GPS)</span>
            <p className="text-[11px] text-gray-500 mb-2">Set the farm location so nearby buyers discover their produce first.</p>
            {lat != null && lng != null ? (
              <div className="flex items-center justify-between bg-green-50 border border-green-200 rounded-xl px-4 py-3">
                <span className="text-sm font-semibold text-green-800">✓ 📍 {locationName || 'Location set'}</span>
                <button type="button" onClick={() => { setLat(null); setLng(null); setLocationName('') }} className="text-xs text-green-700 underline font-semibold">Change</button>
              </div>
            ) : (
              <div className="space-y-2">
                <button
                  type="button"
                  onClick={handleGPS}
                  disabled={locating}
                  className="w-full flex items-center justify-center gap-2 bg-green-700 text-white font-bold py-3 rounded-xl text-sm active:bg-green-800 disabled:opacity-50"
                >
                  {locating ? 'Getting location…' : '📍 Use GPS (most accurate)'}
                </button>
                <div className="flex items-center gap-2">
                  <div className="flex-1 border-t border-gray-200" />
                  <span className="text-[10px] text-gray-400 font-semibold">OR</span>
                  <div className="flex-1 border-t border-gray-200" />
                </div>
                <LocationSearch
                  placeholder="Search farm location"
                  onSelect={(la, ln, nm) => { setLat(la); setLng(ln); setLocationName(nm) }}
                />
              </div>
            )}
            {locError && <p className="text-xs text-red-600 bg-red-50 rounded-xl px-3 py-2 mt-2">{locError}</p>}
          </div>

          <div className="grid md:grid-cols-2 gap-4 mt-4">
            <div>
              <span className="text-[11px] font-bold text-gray-500 uppercase tracking-wide block mb-1">Farm cover photo</span>
              <PhotoUpload preview={cover.preview} onPick={pickPhoto(setCover, cover)} onClear={clearPhoto(setCover, cover)} aspectClass="aspect-[3/1]" />
            </div>
            <div>
              <span className="text-[11px] font-bold text-gray-500 uppercase tracking-wide block mb-1">Farmer photo</span>
              <PhotoUpload preview={avatar.preview} onPick={pickPhoto(setAvatar, avatar)} onClear={clearPhoto(setAvatar, avatar)} aspectClass="aspect-square max-w-[120px]" />
            </div>
          </div>

          <div className="mt-4">
            <span className="text-[11px] font-bold text-gray-500 uppercase tracking-wide block mb-1">Pesticide-free / certification photo (optional)</span>
            <PhotoUpload preview={cert.preview} onPick={pickPhoto(setCert, cert)} onClear={clearPhoto(setCert, cert)} aspectClass="aspect-[3/2] max-w-[200px]" />
          </div>
        </div>

        {/* ── Pickup & payout — mirrors the farmer's own profile ── */}
        <div className="border-t border-gray-100 pt-4">
          <p className="text-sm font-extrabold text-green-800 mb-3">Pickup &amp; payment</p>

          <Field label="Farm address (for pickup)">
            <textarea value={form.farm_address} onChange={set('farm_address')} rows={2} className={inputCls} placeholder="House / street, landmark, village" />
          </Field>

          <div className="mt-4">
            <span className="text-[11px] font-bold text-gray-500 uppercase tracking-wide block mb-1">Pickup locations</span>
            <div className="flex gap-2">
              <input
                value={newPickup}
                onChange={(e) => setNewPickup(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addPickup() } }}
                placeholder="e.g. Market road junction"
                className={inputCls}
              />
              <button type="button" onClick={addPickup} className="bg-green-700 text-white text-sm font-bold px-4 rounded-xl active:bg-green-800 whitespace-nowrap">Add</button>
            </div>
            {pickupLocations.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2">
                {pickupLocations.map((loc) => (
                  <span key={loc} className="inline-flex items-center gap-1 bg-green-50 border border-green-200 text-green-800 text-xs font-semibold px-2.5 py-1 rounded-full">
                    {loc}
                    <button type="button" onClick={() => removePickup(loc)} className="text-green-500 text-sm leading-none">×</button>
                  </span>
                ))}
              </div>
            )}
          </div>

          <div className="grid md:grid-cols-2 gap-4 mt-4">
            <Field label="UPI ID (for payouts)">
              <input value={form.upi_id} onChange={set('upi_id')} placeholder="name@ybl" className={inputCls} />
            </Field>
            <label className="flex items-center gap-2 mt-6">
              <input type="checkbox" checked={codEnabled} onChange={(e) => setCodEnabled(e.target.checked)} className="w-4 h-4 accent-green-700" />
              <span className="text-sm font-semibold text-gray-700">Accepts Cash on Delivery</span>
            </label>
          </div>

          <div className="grid md:grid-cols-2 gap-4 mt-4">
            <Field label="Bank account number">
              <input value={form.bank_account_number} onChange={set('bank_account_number')} inputMode="numeric" placeholder="Account number" className={inputCls} />
            </Field>
            <Field label="IFSC code">
              <input value={form.bank_ifsc} onChange={set('bank_ifsc')} placeholder="SBIN0001234" className={`${inputCls} uppercase`} />
            </Field>
          </div>

          <div className="mt-4">
            <span className="text-[11px] font-bold text-gray-500 uppercase tracking-wide block mb-1">UPI QR code</span>
            <p className="text-[11px] text-gray-500 mb-2">Buyers scan this to pay. Upload a screenshot of their UPI QR.</p>
            <PhotoUpload preview={qr.preview} onPick={pickPhoto(setQr, qr)} onClear={clearPhoto(setQr, qr)} aspectClass="aspect-square max-w-[160px]" />
          </div>
        </div>

        {error && (
          <p className="text-xs text-red-700 bg-red-50 border border-red-200 rounded-xl px-3 py-2 font-semibold">{error}</p>
        )}

        <div className="flex gap-2 pt-1">
          <button
            type="submit"
            disabled={submitting}
            className="bg-green-800 text-white text-sm font-bold px-5 py-3 rounded-xl active:bg-green-900 disabled:opacity-50"
          >
            {submitting ? 'Saving…' : 'Register farmer'}
          </button>
          <button
            type="button"
            onClick={() => router.push('/moderator/farmers')}
            className="bg-white border border-gray-200 text-gray-700 text-sm font-bold px-5 py-3 rounded-xl active:bg-gray-50"
          >
            Cancel
          </button>
        </div>
      </form>
    </ModeratorShell>
  )
}

const inputCls = 'w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:border-green-500 focus:outline-none'

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <label className="block">
      <span className="text-[11px] font-bold text-gray-500 uppercase tracking-wide block mb-1">{label}</span>
      {children}
    </label>
  )
}

// Success card: shows the shareable activation code (copy + WhatsApp) and the
// live profile link, then lets the moderator add another or view their list.
function FarmerCreatedCard({
  created,
  onAddAnother,
  onViewMine,
}: {
  created: Created
  onAddAnother: () => void
  onViewMine: () => void
}) {
  const [copied, setCopied] = useState(false)
  const code = created.activation_code ?? ''
  const origin = typeof window !== 'undefined' ? window.location.origin : ''
  const profileUrl = `${origin}/farmer/${created.slug}`

  const copyCode = async () => {
    try {
      await navigator.clipboard.writeText(code)
      setCopied(true)
      setTimeout(() => setCopied(false), 1800)
    } catch { /* clipboard blocked — moderator can still read the code */ }
  }

  const digits = (created.phone ?? '').replace(/\D/g, '')
  const waPhone = digits.length === 10 ? `91${digits}` : digits
  const waText = encodeURIComponent(
    `Welcome to GoGrameen, ${created.name}! 🌱\n\n`
    + `Your activation code: ${code}\n`
    + `Use it to activate your farmer login.\n\n`
    + `Your farm page is live: ${profileUrl}`,
  )
  const waLink = `https://wa.me/${waPhone}?text=${waText}`

  return (
    <div className="bg-white rounded-2xl border border-gray-100 p-6 max-w-md">
      <div className="text-4xl mb-2">✅</div>
      <h2 className="text-lg font-extrabold text-gray-900">{created.name} is registered</h2>
      <p className="text-sm text-gray-500 mt-1">Share this activation code with the farmer:</p>

      {/* Activation code — the headline of this screen. */}
      <div className="mt-3 bg-green-50 border-2 border-dashed border-green-300 rounded-2xl px-4 py-4 flex items-center justify-between gap-3">
        <span className="text-2xl md:text-3xl font-black tracking-widest text-green-900 font-mono break-all">
          {code || '—'}
        </span>
        <button
          onClick={copyCode}
          disabled={!code}
          className="bg-green-700 text-white text-xs font-bold px-3 py-2 rounded-xl active:bg-green-800 whitespace-nowrap disabled:opacity-50"
        >
          {copied ? 'Copied ✓' : 'Copy'}
        </button>
      </div>

      <p className="text-xs text-gray-500 mt-3">Their profile page is live:</p>
      <a href={`/farmer/${created.slug}`} target="_blank" className="block text-green-700 underline text-sm mt-1 break-all">{profileUrl}</a>

      <div className="flex flex-col gap-2 mt-5">
        {waPhone && (
          <a
            href={waLink}
            target="_blank"
            className="bg-green-600 text-white text-sm font-bold px-4 py-3 rounded-xl text-center active:bg-green-700"
          >
            Send code via WhatsApp
          </a>
        )}
        <button
          onClick={onAddAnother}
          className="bg-white border border-gray-200 text-gray-700 text-sm font-bold px-4 py-3 rounded-xl active:bg-gray-50"
        >
          + Register another farmer
        </button>
        <button onClick={onViewMine} className="text-gray-500 text-sm underline">
          View farmers I registered
        </button>
      </div>
    </div>
  )
}

function PhotoUpload({
  preview,
  onPick,
  onClear,
  aspectClass,
}: {
  preview: string
  onPick: (e: React.ChangeEvent<HTMLInputElement>) => void
  onClear: () => void
  aspectClass: string
}) {
  if (preview) {
    return (
      <div className={`relative ${aspectClass} rounded-xl overflow-hidden border border-gray-200 bg-gray-50`}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={preview} alt="" className="w-full h-full object-cover" />
        <button
          type="button"
          onClick={onClear}
          className="absolute top-2 right-2 bg-white/90 text-gray-700 rounded-full w-7 h-7 flex items-center justify-center text-sm font-bold shadow"
        >
          ×
        </button>
      </div>
    )
  }
  return (
    <label className="flex items-center justify-center gap-2 border-2 border-dashed border-green-300 rounded-xl py-4 px-2 text-green-700 text-xs font-bold cursor-pointer active:bg-green-50">
      <span>📷</span> Add photo
      <input type="file" accept="image/*" onChange={onPick} className="hidden" />
    </label>
  )
}

